import{_ as e,o as s,c as r,a5 as o}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"传参响应式问题：主流处理方式 & 最佳实践","description":"主流处理方式 & 最佳实践 场景 做法 说明 字段本身会变 （💰 动态数据、开关、阈值…） 把字段包成 Signal/Ref/Getter，再传给 useDataItem 示例：decimals: () \\\\ myStore.decimals 或 decimals: decimal。","frontmatter":{"title":"传参响应式问题：主流处理方式 & 最佳实践","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"主流处理方式 & 最佳实践 场景 做法 说明 字段本身会变 （💰 动态数据、开关、阈值…） 把字段包成 Signal/Ref/Getter，再传给 useDataItem 示例：decimals: () \\\\ myStore.decimals 或 decimals: decimal。","sidebarWeight":150,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/响应式问题/传参响应式问题：主流处理方式 & 最佳实践.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/传参响应式问题：主流处理方式 & 最佳实践.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/传参响应式问题：主流处理方式 & 最佳实践.md"}'),a={name:"posts/Vue系统教程/03-响应式与组合式 API/传参响应式问题：主流处理方式 & 最佳实践.md"};function n(i,t,g,l,d,p){return s(),r("div",null,[...t[0]||(t[0]=[o('<div><h1 id="传参响应式问题-主流处理方式-最佳实践" tabindex="-1">传参响应式问题：主流处理方式 &amp; 最佳实践 <a class="header-anchor" href="#传参响应式问题-主流处理方式-最佳实践" aria-label="Permalink to &quot;传参响应式问题：主流处理方式 &amp; 最佳实践&quot;">​</a></h1><blockquote><p>本节目标：理解“传参响应式问题：主流处理方式 &amp; 最佳实践”的核心思路，并能把它用于实际开发或面试表达。 <strong>主流处理方式 &amp; 最佳实践</strong></p></blockquote><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>场景</strong></td><td><strong>做法</strong></td><td><strong>说明</strong></td></tr><tr><td><strong>字段本身会变</strong>（💰 动态数据、开关、阈值…）</td><td><strong>把字段包成 Signal/Ref/Getter，再传给 useDataItem</strong></td><td>示例：decimals: () =&gt; myStore.decimals 或 decimals: decimalsSignal</td></tr><tr><td><strong>字段只在少数场景整体换一批</strong></td><td><strong>直接重新调用 useDataItem 或 setOptions</strong></td><td>React/TanStack 的做法：table.setOptions(prev =&gt; ({ ...prev, decimals }))</td></tr><tr><td><strong>想用一个对象统一改动多个字段</strong></td><td><strong>让整个 options 本身是 Signal/Ref</strong>，内部再分解</td><td>const optionsSig = Signal.state(initOptions); useDataItem(optionsSig); optionsSig.set({ ...old, decimals: 4 })</td></tr></tbody></table><p><strong>一句话</strong>：<strong>要变就给“响应式包装”，要不变就传字面量</strong>； 如果你改的是字面量字段，就必须 <em>换引用</em>，否则没人知道它变了。</p><p><strong>具体改动：让所有可变字段支持 MaybeRefOrGetter</strong></p><ol><li><strong>types.ts</strong></li></ol><p>ts 复制编辑 export interface DataItemOptions { label: string; separator?: MaybeRefOrGetter&lt;string&gt;; /* 动态值 <em>/ value: MaybeRefOrGetter&lt;number&gt;; loading?: MaybeRefOrGetter&lt;boolean&gt;; /</em> 可能在运行期切换的展示配置也给成 MaybeRefOrGetter */ decimals?: MaybeRefOrGetter&lt;number&gt;; extraDigits?: MaybeRefOrGetter&lt;number&gt;; prefix?: MaybeRefOrGetter&lt;string&gt;; suffix?: MaybeRefOrGetter&lt;string&gt;; unit?: MaybeRefOrGetter&lt;string&gt;; formatter?: (v: number) =&gt; string; thresholds?: MaybeRefOrGetter&lt;Thresholds&gt;;}</p><ol><li><strong>useDataItem.ts</strong>****<em>保持你现有逻辑，只确认用 resolve() 解包即可（你已经这么做了）</em></li></ol><p><strong>示例：三种更新方式</strong><strong>① 字段自己是 Signal（最推荐）</strong></p><p>ts 复制编辑 // 假设 decimals 会随用户设置变化const decimalsSig = Signal.state(2) // 调用const item = useDataItem({ label: &#39;价格&#39;, value: priceSig, // Signal decimals: decimalsSig, // Signal prefix: &#39;$&#39;,}) // 修改decimalsSig.set(4) // useDataItem 内部会自动响应 <strong>② 整个 options 是 Signal</strong></p><p>ts 复制编辑 const opts = Signal.state({ label: &#39;价格&#39;, value: priceSig, decimals: 2, prefix: &#39;$&#39;,}) const item = useDataItem(opts) // 批量修改时换引用opts.set({ ...opts.get(), decimals: 4, prefix: &#39;USD &#39; }) <strong>③ 像 TanStack-React 那样：显式 setOptions</strong></p><p>tsx 复制编辑 // React 伪码const [item, setItemOptions] = useState(initOptions) useEffect(() =&gt; { setItemOptions(prev =&gt; ({ ...prev, decimals }))}, [decimals])</p><p><strong>TanStack Table 的做法</strong></p><ul><li><strong>核心库</strong>：只在外层调用 table.setOptions() 时重新读取；<strong>不监听深层字段</strong>。</li><li><strong>React 适配层</strong>：每次组件渲染都会最少调用一次 instance.setOptions(...)，并把依赖写进 useMemo() 里，<strong>依赖变</strong> <strong>⇒</strong> <strong>新引用</strong> <strong>⇒</strong> <strong>Table 重算</strong>。</li><li><strong>Solid / Vue 适配层</strong>：用 createMemo / watchEffect 包住 setOptions，依靠框架 reactivity 感知字段变化。</li></ul><p><strong>同一个模式</strong>：<strong>要么字段自己是 reactive，要么外层换引用并显式 setOptions</strong>。</p><p><strong>结论</strong></p><ul><li><strong>你想变的字段</strong> ➜ 包成 Signal / Ref / Getter 传进去；</li><li><strong>你不想管的静态配置</strong> ➜ 直接字面量；</li><li>如果要一次改动多项 ➜ <strong>要么把整个 options 包成 Signal，要么重新执行 useDataItem / setOptions</strong>。</li></ul><p>遵循这套思路，你的组件就能和 TanStack 一样既保持“核心纯 JS”又能轻松接入各种响应式框架。</p></div>',1)])])}const u=e(a,[["render",n]]);export{c as __pageData,u as default};
